import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateComment } from "../handlers/updateComment";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePostCommentTargetEntityType } from "../types/SpacePostCommentTargetEntityType";
import type { SpacePostEntityType } from "../types/SpacePostEntityType";
import type { UpdateCommentRequest } from "../types/UpdateCommentRequest";

type Data = Awaited<ReturnType<typeof updateComment>>;
type Vars = { spaceId: SpacePartition; discussionSk: SpacePostEntityType; commentSk: SpacePostCommentTargetEntityType; req: UpdateCommentRequest };

export function useUpdateComment(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateComment(vars.spaceId, vars.discussionSk, vars.commentSk, vars.req),
    ...options,
  });
}
